mapper.select:
        select
        subscribes.*,
        users.nick_name,
        users.head_img,
        lawyers.name,
        lawyers.avatar
        from subscribes subscribes
        left join users users on subscribes.user_id = users.id
		left join lawyers lawyers on subscribes.lawyer_id = lawyers.id

            and subscribes.id = #{id}
            and subscribes.user_id = #{userId}
            and subscribes.lawyer_id = #{lawyerId}
            and subscribes.subscribe_time = #{subscribeTime}
            and subscribes.status = #{status}
            and subscribes.create_time = #{createTime}
            and users.nick_name like concat('%',#{nickName},'%')
            and users.head_img = #{headImg}
            and lawyers.name like concat('%',#{name},'%')
            and lawyers.avatar = #{avatar}


            limit #{current},#{pageSize}

        select count(*) from subscribes subscribes
        left join users users on subscribes.user_id = users.id
		left join lawyers lawyers on subscribes.lawyer_id = lawyers.id

            and subscribes.id = #{id}
            and subscribes.user_id = #{userId}
            and subscribes.lawyer_id = #{lawyerId}
            and subscribes.subscribe_time = #{subscribeTime}
            and subscribes.status = #{status}
            and subscribes.create_time = #{createTime}
            and users.nick_name like concat('%',#{nickName},'%')
            and users.head_img = #{headImg}
            and lawyers.name like concat('%',#{name},'%')
            and lawyers.avatar = #{avatar}
